('nifty-50', 'NIFTY 50', 'Nifty 50 Index', 'Index', '24,812.55', -0.18, 'The Nifty 50 is the flagship index of India''s National Stock Exchange, tracking 50 of the country''s largest companies. The Nifty 50 today matters to Nepali investors because the rupee''s peg to the Indian currency ties the two economies closely together.', array['Nifty 50','Nifty today','India stock market','NSE index']::text[], 6),
('ftse-100', 'FTSE 100', 'FTSE 100 Index', 'Index', '8,942.61', 0.22, 'The FTSE 100 tracks the 100 largest companies on the London Stock Exchange. The FTSE 100 today is the benchmark for UK-listed equities and a widely watched gauge for global investors.', array['FTSE 100','FTSE today','UK stock market','London stocks']::text[], 7),
('bitcoin', 'BTC/USD', 'Bitcoin', 'Crypto', '117,420', 2.36, 'Bitcoin (BTC) is the largest cryptocurrency by market value. The Bitcoin price today in USD is the most tracked quote in digital assets, moving on ETF flows, macro liquidity and sentiment across global crypto markets.', array['Bitcoin','bitcoin price today','BTC USD','btc price']::text[], 8),
('ethereum', 'ETH/USD', 'Ethereum', 'Crypto', '4,512.08', 1.12, 'Ethereum (ETH) powers the largest smart-contract network in crypto. The Ethereum price today reflects staking yields, network activity and institutional adoption across the digital-asset economy.', array['Ethereum','ethereum price today','ETH USD','eth price']::text[], 9),
('solana', 'SOL/USD', 'Solana', 'Crypto', '214.60', 2.45, 'Solana (SOL) is a high-throughput blockchain known for fast, low-cost transactions. The Solana price today moves with on-chain activity, decentralized exchange volumes and growing institutional product interest.', array['Solana','solana price today','SOL USD','sol price']::text[], 10),
('gold', 'XAU/USD', 'Gold Spot', 'Commodities', '3,388.40', -0.27, 'Gold spot (XAU/USD) is the global benchmark price for an ounce of gold. The gold price today moves with central-bank buying, real interest rates and safe-haven demand — closely watched in Nepal, where gold is both an investment and a cultural store of value.', array['gold price today','XAU USD','gold spot price','gold rate']::text[], 11),
('brent-crude', 'BRENT', 'Brent Crude Oil', 'Commodities', '82.14', 1.05, 'Brent crude is the global benchmark for oil prices. The Brent crude price today drives fuel costs worldwide and feeds directly into the import bills and inflation outlook of oil-importing economies like Nepal.', array['Brent crude','oil price today','crude oil price','brent price']::text[], 12),
('usd-npr', 'USD/NPR', 'US Dollar to Nepali Rupee', 'Forex', '137.62', -0.05, 'USD/NPR is the exchange rate between the US dollar and the Nepali rupee. The dollar to rupee rate today matters to every household receiving remittances, every importer, and every traveler — making it Nepal''s most searched currency quote.', array['USD to NPR','dollar rate in nepal today','usd npr exchange rate','aaja ko dollar rate']::text[], 13),
('eur-usd', 'EUR/USD', 'Euro to US Dollar', 'Forex', '1.1684', 0.09, 'EUR/USD is the most traded currency pair in the world. The euro to dollar rate today reflects the interest-rate gap between the European Central Bank and the Federal Reserve.', array['EUR USD','euro to dollar','eurusd today','euro dollar rate']::text[], 14),
('usd-jpy', 'USD/JPY', 'US Dollar to Japanese Yen', 'Forex', '147.30', -0.33, 'USD/JPY tracks the dollar against the Japanese yen. The dollar-yen rate today is among the most liquid forex quotes globally and a sensitive gauge of Bank of Japan policy expectations.', array['USD JPY','dollar to yen','usdjpy today','yen rate']::text[], 15),
('nvidia', 'NVDA', 'NVIDIA Corporation', 'Stocks', '182.44', 2.87, 'NVIDIA (NVDA) designs the chips powering the global AI buildout. The NVIDIA share price today is one of the most traded quotes in the world and a proxy for sentiment toward artificial-intelligence investment.', array['NVIDIA','NVDA stock price','nvidia share price today','NVDA stock']::text[], 16),
('tesla', 'TSLA', 'Tesla Inc.', 'Stocks', '241.03', -1.92, 'Tesla (TSLA) is the world''s most watched electric-vehicle maker. The Tesla share price today swings on delivery numbers, margins and the company''s energy and autonomy ambitions.', array['Tesla','TSLA stock price','tesla share price today','TSLA stock']::text[], 17);

