insert into public.glossary_terms (slug, term, definition, body, keywords, sort_order) values
('what-is-nepse', 'What is NEPSE?', 'NEPSE is the Nepal Stock Exchange, the country''s only stock exchange, where shares of banks, hydropower companies and other listed firms trade Sunday to Thursday.', 'The Nepal Stock Exchange (NEPSE) is Nepal''s only stock exchange, established in 1994 and headquartered in Kathmandu. It lists commercial banks, development banks, hydropower companies, insurers, microfinance institutions and other public companies.

NEPSE trades Sunday through Thursday, 11:00 AM to 3:00 PM Nepal time, and remains closed on Fridays, Saturdays and public holidays. The NEPSE Index tracks the overall market, while sub-indices cover sectors like banking and hydropower.

Most trading happens through a broker using an online TMS (Trade Management System) account, with settlement handled via CDS and Clearing. For most Nepali investors, the NEPSE index level and daily turnover are the first numbers they check each day.', array['NEPSE','Nepal Stock Exchange','what is nepse','nepse trading hours','nepali share market']::text[], 0),
('market-capitalization', 'Market Capitalization', 'Market capitalization is the total value of a company''s shares — its share price multiplied by the number of shares outstanding.', 'Market capitalization (market cap) measures the total value the stock market assigns to a company. It equals the current share price multiplied by the total number of shares outstanding.

Investors use market cap to compare company size: a bank trading at NPR 500 with 270 million shares has a market cap of about NPR 135 billion. Large-cap companies tend to be more stable, while small-cap companies can grow faster but swing more in price.

On NEPSE, commercial banks and large hydropower developers carry the biggest market caps, which is why their price moves dominate the index.', array['market cap','market capitalization','company valuation','large cap','small cap']::text[], 1),
('dividend', 'Dividend', 'A dividend is a portion of a company''s profit paid out to shareholders, in cash or as bonus shares.', 'A dividend is a distribution of a company''s earnings to its shareholders. Companies can pay cash dividends directly to bank accounts or issue bonus shares that increase the number of shares each investor holds.

In Nepal, dividends are a major reason investors hold bank and hydropower shares. NEPSE-listed companies typically declare dividends after their fiscal year ends in mid-July, subject to approval at the annual general meeting.

The dividend yield — annual dividend divided by share price — lets investors compare income potential across stocks. A share trading at NPR 500 paying NPR 25 per year yields 5%.', array['dividend','bonus shares','cash dividend','dividend yield','NEPSE dividend']::text[], 2),
('circuit-breaker', 'Circuit Breaker', 'A circuit breaker is an automatic trading halt that pauses the market when prices move too far, too fast, giving investors time to absorb news.', 'A circuit breaker is an automatic mechanism that temporarily halts trading when prices fall or rise beyond a set threshold. Its purpose is to cool panic or mania and give the market time to process new information.

On NEPSE, index-level circuit breakers pause trading across the whole market when the index moves sharply within a session, while individual stocks have daily price limits — often called upper and lower circuits — beyond which they cannot trade that day.

Circuit breakers do not stop a trend; they slow it. Traders watch circuit-hit stocks closely because the next session often opens with pent-up orders.', array['circuit breaker','upper circuit','lower circuit','trading halt','NEPSE circuit']::text[], 3),
('bull-and-bear-market', 'Bull and Bear Market', 'A bull market is a sustained period of rising prices and optimism; a bear market is a sustained decline, usually 20% or more from a peak.', 'Markets move in broad cycles. A bull market describes a sustained rise in prices accompanied by optimism and growing participation; a bear market describes a sustained decline, conventionally 20% or more from a recent high, accompanied by pessimism.

The names come from how each animal attacks: bulls thrust their horns upward, bears swipe downward. NEPSE has seen both — multi-year bull runs driven by cheap credit and new listings, and bear phases when liquidity tightened.

Neither lasts forever. Long-term investors generally care less about labeling the market and more about buying quality assets at sensible prices.', array['bull market','bear market','market cycle','stock market trend']::text[], 4),
('pe-ratio', 'P/E Ratio', 'The price-to-earnings ratio compares a company''s share price to its earnings per share, showing how much investors pay for each rupee of profit.', 'The price-to-earnings (P/E) ratio divides a company''s share price by its earnings per share (EPS). A stock trading at NPR 500 with EPS of NPR 50 has a P/E of 10 — investors pay 10 rupees for every rupee of annual profit.

A high P/E suggests investors expect strong future growth; a low P/E can signal an undervalued stock or a company facing trouble. P/E is most useful when comparing companies in the same sector, like two commercial banks on NEPSE.

The P/E ratio says nothing by itself about risk, balance-sheet strength or dividend quality, so investors combine it with other measures.', array['P/E ratio','price to earnings','EPS','stock valuation','NEPSE valuation']::text[], 5),
('ipo', 'IPO (Initial Public Offering)', 'An IPO is a company''s first sale of shares to the public, letting anyone apply to become a shareholder through the exchange.', 'An initial public offering (IPO) is the first time a company sells its shares to the general public. In Nepal, IPO applications go through the Mero Share platform using an ASBA-linked bank account, making the process accessible to small investors.

NEPSE IPOs are frequently oversubscribed many times over, so allotments are often decided by lottery. Hydropower IPOs in particular draw millions of applications because of the sector''s popularity with retail investors.

After allotment, shares are listed on NEPSE and can be traded freely. An IPO''s first-day price can jump well above its issue price — but that premium is never guaranteed.', array['IPO','initial public offering','Mero Share','ASBA','NEPSE IPO','hydropower IPO']::text[], 6),
('liquidity', 'Liquidity', 'Liquidity describes how easily an asset can be bought or sold without moving its price — high-turnover stocks are liquid, thinly traded ones are not.', 'Liquidity measures how quickly and cheaply you can convert an asset to cash. A liquid stock trades in large volumes every day, so you can sell without pushing the price down; an illiquid stock may have few buyers at any moment.

On NEPSE, commercial bank shares are highly liquid while some small companies trade only a handful of times per session. Daily turnover — the total rupee value traded — is the market''s broadest liquidity gauge.

Liquidity also describes the banking system itself: when Nepal Rastra Bank tightens money supply, loanable funds shrink, interest rates rise, and the stock market often cools.', array['liquidity','turnover','trading volume','NRB liquidity','liquid stocks']::text[], 7),
('portfolio-diversification', 'Portfolio Diversification', 'Diversification means spreading money across different assets and sectors so that one bad investment cannot sink the whole portfolio.', 'Diversification is the practice of spreading investments across different assets, sectors and markets so no single loss can seriously damage the whole portfolio. It is often summarized as ''don''t put all your eggs in one basket.''

A Nepali investor might diversify across banking and hydropower stocks, add fixed deposits, hold some gold, and keep cash for emergencies. Global investors add foreign indices and bonds to the mix.

Diversification reduces risk but cannot eliminate it. When entire markets fall together — as in a broad bear market — even diversified portfolios decline, just usually less severely.', array['diversification','portfolio','asset allocation','risk management','investment portfolio']::text[], 8),
('exchange-rate', 'Exchange Rate', 'An exchange rate is the price of one currency in terms of another — for example, how many Nepali rupees one US dollar buys today.', 'An exchange rate expresses the value of one currency in another. When USD/NPR is 137.62, one US dollar buys 137.62 Nepali rupees. Rates move with interest-rate differences, trade balances, inflation and capital flows.

Nepal''s rupee is pegged to the Indian rupee at a fixed rate, so USD/NPR largely follows the dollar-rupee (USD/INR) market. Remittances from Nepali workers abroad are the country''s biggest source of foreign currency, making the dollar rate a household topic.

For traders, exchange rates are themselves a market: forex pairs like EUR/USD and USD/JPY are the most traded instruments in the world.', array['exchange rate','USD NPR','dollar rate','forex','currency peg','remittance']::text[], 9);

